    return lerp(hf(kA>>0),hf(kB>>0),0.5);
  };
  const h=new Float32Array(gx*gy);
  const b=new Uint8Array(gx*gy);
  const ns=new Float32Array(gx*gy*3);
  const wc=new Float32Array(gx*gy); // water coverage 0..1
  for(let i=0;i<gx;i++){
    for(let j=0;j<gy;j++){
      const x=(i-gx/2)*CELL, y=(j-gy/2)*CELL;
      let nm=noise2(x*.25,y*.32); h[idx(i,j)]=nm*1.1; // altura bruta
      // bioma por distância do centro
      const dx=x-CX0,dy=y-CY0, d=Math.hypot(dx,dy);
      let bio=7; // água por padrão
      if(d<300) bio=0; else if(d<720) bio=1; else if(d<1160) bio=2;
      else if(d<1620) bio=3; else if(d<2100) bio=4; else if(d<2580) bio=6; else bio=5;
      if(d<1700 && Math.abs(y-CY0)<260) bio=7; // rio central
      // lagos
      if(Math.abs(x-CX0)<700 && Math.abs(y-CY0)<700 && d<900) bio=7;
      // mistura suave nas bordas dos biomas
      let t=0;
      if(bio!==0) t+=smoothstep(0,300,d*1.06)/3; // cidade
      if(bio!==1) t+=smoothstep(0,420,Math.min((d-700)/420,1))/3;
      if(bio!==2) t+=smoothstep(0,560,Math.min((d-1100)/560,1))/3;
      if(bio!==3) t+=smoothstep(0,760,Math.min((d-1500)/760,1))/3;
      if(bio!==4) t+=smoothstep(0,1100,Math.min((d-1900)/1100,1))/2;
      b[idx(i,j)]=bio;
      // cores
      const bc=BIOHC[bio];
      const nb=bc.concat();
      for(let k=0;k<3;k++) nb[k]+=0.15; // leve brilho base
      let col=new Float32Array(3);
      const s=clamp01(t);
      // pegar cor do bioma vizinho para transição
      const ni=Math.min(gx-2,Math.max(0,idx(i,j)+1)), nj=Math.min(gy-1,Math.max(0,j+1));
      const nc=Math.min(gx-2,Math.max(0,idx(i,j)-1)), nd=Math.min(gy-1,Math.max(0,j-1));
      for(let kk=0;kk<3;kk++) col[kk]=lerp(ncol[kk],nb[kk],s);
      // agua fica mais azul profunda conforme profundidade
      if(bio===7){
        const hd=Math.max(0,0.55-H[idx(j,i)]); // depressão do terreno
        wc[idx(i,j)]=Math.min(1,hd/2.4);
        col[0]*=(1-.25*wc[idx(i,j)]); col[1]*=1+.15*wc[idx(i,j)]; col[2]*=1+.1*wc[idx(i,j)];
      }
      for(let k=0;k<3;k++) col[k]=clamp01(col[k]);
