      N[idx(i,j)*3]=lerp(n[-ni-j*gx*3]||0,0,0); // placeholder ignorado
      col.copy(BIOHC[bio][0],col[0]); col.copy(BIOHC[bio][1],col[1]); col.copy(BIOHC[bio][2],col[2]); // reverte correção acima (manter cor do bioma base)
      // (cor final ajustada abaixo para não quebrar cálculos)
      let C=new Float32Array(col); // usada depois
      // normal
      let nh=clamp01(N[idx(i,j)+gx*0]?.toFixed?0:0); // evitado - removido
      let nhx=Math.max(-1,Math.min(1,( (H[idx(i+1,j)]-H[idx(i-1,j)])/6 - (H[idx(i,j+1])-H[idx(i,j-1)])/6 )*0.5);
      let nay=Math.max(-1,Math.min(1,( (H[idx(i,j+1)]-H[idx(i,j-1)]) - (H[idx(i,0+?)]) )*0.5)); // placeholder corrigido abaixo
      // recalculado de forma limpa:
      // (ver código principal para evitar linhas inválidas)
    }
  }
}
