## 🚀 8. Entrada do bot — `src/main.js`

```js
import dotenv from 'dotenv';
dotenv.config();

import { Client, Commands } from 'discord.js';
import { comandos } from './handlers/index.js';
import { settings } from './settings.js';

const client = new Client({ intents: ['GuildMessages'] });
client.commands = new Commands(comandos); // <- registra os slash commands

client.on('interactionCreate', async (interaction) => {
  // ------------------------------------------------------------------
  // BARA DE COMANDOS (slash commands — estilo moderno /extrair-pdf)
  // ------------------------------------------------------------------
  if (interaction.commandType === 'SlashCommand') {
    // Ack imediato e invisível — obrigatório em slash commands
    await interaction.response.sendData({});

    const handler = comandos[interaction.name];
    if (!handler) {
      await interaction.editReply({
        content: '❌ Comando não encontrado. Consulte `/ajuda` para ver a lista.',
        ephemeral: true,
        duration: 5000,
      });
      return;
    }

    try {
      await handler(interaction); // o handler cuida de enviar as mensagens
    } catch (err) {
      console.error('[bot] Erro no comando', err);
      await interaction.editReply({
        content: `❌ **Erro:** ${err.message || 'Algo inesperado aconteceu.'}`,
        ephemeral: true,
        duration: 5000,
      });
    }
    return;
  }

  // ------------------------------------------------------------------
  // COMANDOS POR MENSAGEM (prefixo "!" — opcional, deixe descomentado se quiser)
  // ------------------------------------------------------------------
  if (
    interaction.commandType === 'MessageCommand' &&
    !interaction.isReply() &&
    (interaction.isMessageInChannel() || interaction.isDirect())
  ) {
    await interaction.reply({ filter: true }); // "lá, estou aqui 👋"

    const handler = comandos[interaction.name];
    if (!handler) {
      await interaction.channel.send({
        content: '❌ Comando não encontrado. Use `/ajuda` para listar os comandos.',
        ephemeral: true,
      });
      return;
    }

    try {
      await handler(interaction);
    } catch (err) {
      console.error('[bot] Erro no comando com prefixo:', err);
      await interaction.channel.send({
        content: `❌ **Erro:** ${err.message || 'Algo deu errado.'}`,
        ephemeral: true,
      });
      return;
    }
  }
});

client.login(settings.botToken).then(() => console.log('✅ Bot online!'), (err) => {
  console.error('❌ Falha ao iniciar:', err);
  process.exit(1);
});
```

> **Nota:** o bloco final (mensagem com `!`) está comentado como opção. É fácil habilitar/remover seguindo os mesmos padrões — só precisa criar um listener `message` que parseie `!extrair-pdf`.

